import { cartTotal, hasDuplicateSku, isValidCart } from "./cart"
import type { CartItem } from "./cart"
import { grantCredit, spendCredit } from "./credit"
import { applyDiscount } from "./discount"
import { reserve, release } from "./inventory"
import { sendConfirmation } from "./mail"
import type { Cents } from "./money"
import { saveOrder } from "./store"

export interface Customer {
    id: string
    email: string
}

export interface OrderOptions {
    tags: string[]
    discountCode?: string
    payWithCredit?: boolean
}

export type OrderStatus = "pending" | "paid" | "failed" | "cancelled" | "partially_refunded" | "refunded"

export interface Order {
    id: string
    customer: Customer
    items: CartItem[]
    /*  amount before the discount code was applied, kept for the invoice  */
    subtotal: Cents
    total: Cents
    tags: string[]
    status: OrderStatus
    /*  day the order was placed and day the parcel was handed over  */
    placedOn: string
    deliveredOn?: string
    /*  set when store credit paid for the order  */
    paidWith?: "credit"
}

const MIN_ORDER_CENTS = 1000
const DEFAULT_OPTIONS: OrderOptions = { tags: [] }

let nextId = 1

function releaseAll(items: CartItem[]): void {
    for (const item of items)
        release(item.sku, item.quantity)
}

export async function createOrder(
    customer: Customer,
    items: CartItem[],
    options: OrderOptions = DEFAULT_OPTIONS,
    today: string = new Date().toISOString().slice(0, 10)
): Promise<Order> {
    if (!isValidCart(items))
        throw new Error("invalid cart")
    const tags = [...options.tags]
    if (items.some((item) => item.quantity >= 10))
        tags.push("bulk")

    const sorted = [...items].sort((a, b) => a.sku.localeCompare(b.sku))
    if (hasDuplicateSku(sorted))
        throw new Error("duplicate SKU in order")

    const reservedItems: CartItem[] = []
    for (const item of items) {
        if (!reserve(item.sku, item.quantity)) {
            releaseAll(reservedItems)
            throw new Error(`not enough stock for ${item.sku}`)
        }
        reservedItems.push(item)
    }

    const subtotal = cartTotal(items)
    const total    = applyDiscount(subtotal, options.discountCode, today)
    if (total < MIN_ORDER_CENTS) {
        releaseAll(reservedItems)
        throw new Error("order below minimum value")
    }

    const order: Order = {
        id:       `O${nextId++}`,
        customer,
        items,
        subtotal,
        total,
        tags,
        status:   "pending",
        placedOn: today
    }
    if (options.payWithCredit === true) {
        try {
            await spendCredit(customer.id, total, `order ${order.id}`)
        }
        catch (err) {
            releaseAll(reservedItems)
            throw err
        }
        order.paidWith = "credit"
        markPaid(order)
    }
    let stored: Order
    try {
        stored = await saveOrder(order)
    }
    catch (err) {
        releaseAll(reservedItems)
        if (order.paidWith === "credit")
            await grantCredit(customer.id, total, `order ${order.id} not stored`)
        throw err
    }
    await sendConfirmation(stored, options.discountCode)
    return stored
}

/*  whether money was collected for the order and can still be paid back  */
export function hasPayment(order: Order): boolean {
    return order.status === "paid" || order.status === "partially_refunded"
}

/*  the provider confirmed the payment; the reservation becomes a sale  */
export function markPaid(order: Order): void {
    if (order.status !== "pending")
        throw new Error(`order ${order.id} is not pending`)
    order.status = "paid"
}

/*  the provider declined the payment; the items go back on sale  */
export function markFailed(order: Order): void {
    if (order.status !== "pending")
        throw new Error(`order ${order.id} is not pending`)
    releaseAll(order.items)
    order.status = "failed"
}

/*  the customer cancelled before paying  */
export function cancelOrder(order: Order): void {
    if (order.status !== "pending")
        throw new Error(`order ${order.id} cannot be cancelled`)
    releaseAll(order.items)
    order.status = "cancelled"
}

/*  the carrier handed the parcel over  */
export function markDelivered(order: Order, day: string): void {
    if (!hasPayment(order))
        throw new Error(`order ${order.id} is not paid`)
    order.deliveredOn = day
}

/*  money was paid back; the order is refunded once nothing of its total is left  */
export function markRefund(order: Order, paidBack: Cents): void {
    if (!hasPayment(order))
        throw new Error(`order ${order.id} is not paid`)
    order.status = paidBack >= order.total ? "refunded" : "partially_refunded"
}

/*  the status in words, for the account page  */
export function statusText(order: Order): string {
    switch (order.status) {
        case "pending":
            return "waiting for payment"
        case "paid":
            return "paid"
        case "failed":
            return "payment failed"
        case "cancelled":
            return "cancelled"
        case "partially_refunded":
            return "partly refunded"
        case "refunded":
            return "refunded"
    }
}
import { toCents } from "./money"
import type { Cents } from "./money"

export interface CartItem {
    sku: string
    name: string
    unitPrice: number
    quantity: number
}

/*  article numbers are upper-case letters and digits in groups joined by hyphens  */
const SKU_PATTERN = /^[A-Z0-9]+(-[A-Z0-9]+)*$/

/*  total of all items in cents  */
export function cartTotal(items: CartItem[]): Cents {
    let total = 0
    for (const item of items)
        total += toCents(item.unitPrice) * item.quantity
    return total
}

/*  number of units over all items  */
export function countUnits(items: CartItem[]): number {
    let units = 0
    for (let i = 0; i < items.length; i++)
        units += items[i].quantity
    return units
}

/*  whether the cart has items and every item has a well-formed article number,
    a positive price, and a positive whole quantity  */
export function isValidCart(items: CartItem[]): boolean {
    return items.length > 0
        && items.every((item) => SKU_PATTERN.test(item.sku)
            && item.unitPrice > 0
            && Number.isSafeInteger(item.quantity) && item.quantity > 0)
}

/*  whether two neighbouring items share a SKU (items sorted by SKU)  */
export function hasDuplicateSku(items: CartItem[]): boolean {
    for (let i = 0; i < items.length - 1; i++)
        if (items[i].sku === items[i + 1].sku)
            return true
    return false
}
export type Cents = number

export function toCents(euro: number): Cents {
    return Math.round(euro * 100)
}

export function formatAmount(amount: Cents): string {
    return `${(amount / 100).toFixed(2)} EUR`
}
import type { Order } from "./order"

const orders = new Map<string, Order>()

/*  the store keeps its own record, so later changes to the caller's object stay out of it  */
function toRecord(order: Order): Order {
    return {
        id:          order.id,
        customer:    { ...order.customer },
        items:       order.items.map((item) => ({ ...item })),
        subtotal:    order.subtotal,
        total:       order.total,
        tags:        [...order.tags],
        status:      order.status,
        placedOn:    order.placedOn,
        deliveredOn: order.deliveredOn
    }
}

/*  store a new order and hand back the stored record  */
export async function saveOrder(order: Order): Promise<Order> {
    if (orders.has(order.id))
        throw new Error(`order ${order.id} already exists`)
    const record = toRecord(order)
    orders.set(order.id, record)
    return record
}

export async function loadOrder(id: string): Promise<Order | undefined> {
    return orders.get(id)
}

export async function ordersOf(customerId: string): Promise<Order[]> {
    return [...orders.values()].filter((o) => o.customer.id === customerId)
}

export async function allOrders(): Promise<Order[]> {
    return [...orders.values()]
}
import type { Cents } from "./money"
import type { Order } from "./order"

export interface DayReport {
    day: string
    orders: number
    revenue: Cents
}

/*  what the orders of a list brought in  */
export function revenue(orders: Order[]): Cents {
    let sum = 0
    for (const order of orders)
        if (order.status === "paid")
            sum += order.total
    return sum
}

/*  number of orders per status, for the dashboard  */
export function countByStatus(orders: Order[]): Map<string, number> {
    const counts = new Map<string, number>()
    for (const order of orders)
        counts.set(order.status, (counts.get(order.status) ?? 0) + 1)
    return counts
}

/*  one line per day on which orders were placed, oldest day first  */
export function dailyReport(orders: Order[]): DayReport[] {
    const days = new Map<string, Order[]>()
    for (const order of orders) {
        const list = days.get(order.placedOn) ?? []
        list.push(order)
        days.set(order.placedOn, list)
    }
    return [...days.keys()].sort().map((day) => {
        const list = days.get(day) ?? []
        return { day, orders: list.length, revenue: revenue(list) }
    })
}
import { formatAmount } from "./money"
import type { Order } from "./order"
import type { Refund } from "./refund"
import type { ReturnLine } from "./returns"

export interface Mail {
    to: string
    subject: string
    html: string
}

const outbox: Mail[] = []

export function escapeHtml(text: string): string {
    return text
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
}

/*  confirmation mail; the discount code is the one the customer typed into the order form  */
export function renderConfirmation(order: Order, code: string | undefined): string {
    const lines = [
        `<h1>Thank you for your order</h1>`,
        `<p>Order ${escapeHtml(order.id)} for ${escapeHtml(order.customer.email)} is confirmed.</p>`
    ]
    if (code !== undefined)
        lines.push(`<p>Your code ${escapeHtml(code)} was applied.</p>`)
    return lines.join("\n")
}

/*  what came back and what is paid back for it  */
function renderReturnConfirmation(order: Order, lines: ReturnLine[], refund: Refund): string {
    const rows = lines.map((line) => `<li>${line.quantity} x ${line.sku}</li>`)
    const target = refund.method === "credit" ? "as store credit" : "to your payment method"
    return [
        `<h1>We received your return</h1>`,
        `<p>Order ${escapeHtml(order.id)}:</p>`,
        `<ul>${rows.join("")}</ul>`,
        `<p>${formatAmount(refund.amount)} will be paid back ${target}.</p>`
    ].join("\n")
}

export function outboxSize(): number {
    return outbox.length
}

/*  the mails waiting to be sent, oldest first  */
export function queuedMails(): readonly Mail[] {
    return outbox
}

function queueMail(mail: Mail): void {
    if (!/^[^@\s]+@[^@\s]+$/.test(mail.to))
        throw new Error(`invalid recipient ${mail.to}`)
    outbox.push(mail)
}

export async function sendConfirmation(order: Order, code?: string): Promise<void> {
    try {
        queueMail({
            to:      order.customer.email,
            subject: `Your order ${order.id}`,
            html:    renderConfirmation(order, code)
        })
    }
    catch (err) {
        /*  the order is already stored; a bad address must not turn it into a failed order  */
        console.error(`mail for ${order.id} not queued`, err)
    }
}

export async function sendReturnConfirmation(order: Order, lines: ReturnLine[], refund: Refund): Promise<void> {
    try {
        queueMail({
            to:      order.id,
            subject: `Your return for order ${order.id}`,
            html:    renderReturnConfirmation(order, lines, refund)
        })
    }
    catch (err) {
        console.error(`mail for the return of ${order.id} not queued`, err)
    }
}
